export const ATAN_STEP = 0.024413354694843292;          // flt_8650B8 (0x3CC7FE84) as double
export const ATAN_SATURATION = 1.5707964;     // 0x3FC90FDB

// F2I64 (Game::F2I64 0x7C5F00): truncate toward zero.
export function F2I64(v: number): number {
  return v < 0 ? Math.ceil(v) : Math.floor(v);
}

// kUnitScale (Random_w scale dbl_7ED898) = 2^-32 * (1 + 2^-32).
export const K_UNIT_SCALE = 2.3283064370807974e-10;

// YRMath::sqrt (0x4cac40) - bit-exact; returns float32 like the fstp.
export function yrSqrt(a1: number): number {
  if (a1 === 0) return 0;
  if (a1 < 0) a1 = -a1;
  let u = Math.fround(a1);
  let bits = new Uint32Array(new Float32Array([u]).buffer)[0]!;
  let mant = bits & 0x7fffff;
  const e = (bits >>> 23) - 127;
  if (e & 1) mant |= 0x800000;
  bits = (((e >> 1) + 127) << 23) + SQRT_TABLE[mant >>> 10]!;
  return new Float32Array(new Uint32Array([bits]).buffer)[0]!;
}

// sub_4CADE0 - table atan; index truncates toward zero, saturates at 4097.
export function tableAtan(x: number): number {
  const index = F2I64(Math.abs(x) / ATAN_STEP);
  const v = index >= 4097 ? ATAN_SATURATION : ATAN_TABLE[index]!;
  return x < 0 ? -v : v;
}
